import { describe, it, expect } from 'vitest';
import { existsSync, readFileSync } from 'fs';
import { resolve } from 'path';
import { gzipSync } from 'zlib';
import { emojiFor } from '../emojiTable';

// F6 T2 table. Pinned: emojiFor(name) -> string | undefined, exact-case lookup over gemoji names AND aliases
// (all lowercase in gemoji 8.x). Generated by scripts/gen-emoji-table.mjs from the gemoji devDependency, committed.
// The table is NOT filtered by lezer's name rule: names lezer can't parse (+1, -1, t-rex, e-mail, non-potable_water)
// may be in it; the parser decides what is looked up. Prototype keys must be unknown.
const root = process.cwd();

describe('emojiFor: lookup', () => {
    it.each([
        ['smile', '\u{1F604}'],
        ['thumbsup', '\u{1F44D}'],
        ['+1', '\u{1F44D}'],          // alias, in the table even though lezer can't parse it
        ['heart', '❤️'],
        ['tada', '\u{1F389}'],
        ['100', '\u{1F4AF}'],
        ['white_check_mark', '✅'],
        ['email', '\u{1F4E7}'],
    ])('%s -> %s', (name, emoji) => {
        expect(emojiFor(name)).toBe(emoji);
    });
    it('names and aliases of one emoji agree', () => {
        expect(emojiFor('thumbsup')).toBe(emojiFor('+1'));
        expect(emojiFor('thumbsdown')).toBe(emojiFor('-1'));
        expect(emojiFor('email')).toBe(emojiFor('e-mail'));
    });
    it('returns a string for known names', () => {
        expect(typeof emojiFor('smile')).toBe('string');
    });
    it.each(['notanemoji', '', ' smile', 'smile ', ':smile:', 'SMILE', 'Smile'])('unknown %j -> undefined (exact, case-sensitive)', (n) => {
        expect(emojiFor(n)).toBeUndefined();
    });
    it.each(['__proto__', 'constructor', 'toString', 'hasOwnProperty', 'valueOf', 'isPrototypeOf', '__defineGetter__', 'prototype'])(
        'prototype key %s -> undefined', (k) => {
            expect(emojiFor(k)).toBeUndefined();
        });
    it.each([undefined, null, 5, {}, []])('non-string %j -> undefined, no throw', (v) => {
        expect(emojiFor(v)).toBeUndefined();
    });
});

describe('emoji table: size and generation', () => {
    const file = resolve(root, 'src/utils/emojiTable.js');
    it('generated file is committed and gzips to <= 20 KB', () => {
        expect(existsSync(file)).toBe(true);
        expect(gzipSync(readFileSync(file)).length).toBeLessThanOrEqual(20 * 1024);
    });
    it('generator script exists and gemoji is a devDependency (not a runtime dependency)', () => {
        expect(existsSync(resolve(root, 'scripts/gen-emoji-table.mjs'))).toBe(true);
        const pkg = JSON.parse(readFileSync(resolve(root, 'package.json'), 'utf8'));
        expect(pkg.devDependencies).toHaveProperty(['gemoji']);
        expect(pkg.dependencies || {}).not.toHaveProperty(['gemoji']);
    });
    it('the app source never imports gemoji (only the committed map ships)', () => {
        const src = readFileSync(file, 'utf8');
        expect(src).not.toMatch(/from\s*['"]gemoji['"]|require\(\s*['"]gemoji['"]/);
    });
});

// Sync guard: skipped when gemoji is not installed (CI without devDependencies); otherwise every name must match.
const spec = 'gemoji';
const gem = await import(/* @vite-ignore */ spec).catch(() => null);
describe.skipIf(!gem)('emoji table is in sync with gemoji', () => {
    it('every gemoji name and alias maps to its emoji', () => {
        const bad = [];
        let n = 0;
        for (const g of gem.gemoji) for (const name of g.names) { n++; if (emojiFor(name) !== g.emoji) bad.push(name); }
        expect(n).toBeGreaterThan(1800);
        expect(bad).toEqual([]);
    });
});
